int do_move(string arg)
{
    if (!arg || arg == "")
        return 0;

    if (arg == "table")
    {
        write(HIY "\n你用尽了全身力气想移动石桌，可是它犹如在地面"
                  "生根一般，纹丝不动。\n" NOR);
        return 1;
    }
}

int do_swim()
{
        int c_skill;
        object me = this_player();

        c_skill = me->query_skill("jinyan-gong", 1);

        if (me->query("qi") < 40)
                return notify_fail("你现在体力不支，没有力气游泳。\n");

        me->receive_damage("qi", 20 + random(20));
        message_vision("$N在太乙池中划了划水，用力游了起来。\n", me);
        if (c_skill < 1)
                return 1;

        if (me->can_improve_skill("jinyan-gong") && c_skill < 51)
                me->improve_skill("jinyan-gong", 1 + me->query_skill("jinyan-gong", 1) / 15);
        return 1;
}

int do_knock(string arg)
{
    object me;
    mapping mine;

    me = this_player();
    if ( !arg || ( arg != "bell" ) ) return notify_fail("你要敲什麽？\n");

    me->add("qi", -20);


    mine = me->query_entire_dbase();
    message_vision("$N敲了一下大钟，『咣……』声音传遍整个寺庙。\n", me);
    write("钟声如迅雷般在你耳边炸响，你头脑中一片糊涂，\n"
        "全身摇摇欲坠，勉力支撑着不倒在地上。心中一个\n"
        "声音告诉你，得赶快离开这里，不然就没命了。\n");

        if (random(2)==0) mine["combat_exp"] += 1;
        else mine["combat_exp"] -= 2;
    return 1;
}

int do_lopen(string arg)
{
        object me;

        me = this_player();
        if (wiz_level(me) < 3)
                return notify_fail("你没有资格打开擂台。\n");

        if (! objectp(query("close_by")))
                return notify_fail("这个擂台目前并没有被关闭。\n");

        if (arg != "here")
                return notify_fail("如果你要打开擂台，请输入(lopen here)。\n");

        delete("close_by");
        message("vision", HIW "【武林盛会】" + me->name(1) +
                "结束了比武，重新开放了擂台。\n" NOR, all_interactive());
        return 1;
}

int do_finger()
{
        object me;
        int qi_cost, c_skill;

        me = this_player();
        c_skill=me->query_skill("finger", 1);

        message_vision(HIY "$N" HIY "伸指狠狠地点向沙袋，觉得指尖微微"
                       "有些痛。\n" NOR, me);
        qi_cost = 25;

        if (me->query("qi") > qi_cost)
        {
                if (me->can_improve_skill("finger") && c_skill < 100)
        {
                    me->improve_skill("finger", 1 + random(me->query("str")));
                tell_object(me, HIC "你对「基本指法」有了新的领悟。\n" NOR);
        }
                me->receive_damage("qi", qi_cost);
        }
        return 1;
}

int do_strike()
{
        object me;
        int qi_cost, c_skill;

        me = this_player();
        c_skill = me->query_skill("strike", 1);

        message_vision(HIY "$N" HIY "蹲了一个马步，挥起一掌猛击向牛皮"
                       "纸册。\n" NOR, me);
        qi_cost = 25;

        if (me->query("qi") > qi_cost)
        {
                if (me->can_improve_skill("strike") && c_skill < 100)
        {
                    me->improve_skill("strike", 1 + random(me->query("str")));
                tell_object(me, HIC "你对「基本掌法」有了新的领悟。\n" NOR);
        }
                me->receive_damage("qi", qi_cost);
        }
        return 1;
}

int do_broadcast(string arg)
{
        string type;
        string mesg;
        object me;

        me = this_player();
        if (query("order_owner") != me->query("id"))
                return 0;
        type = query("order_type");
        if (type == "party") {
                mesg = me->name() + "在杭州楼外楼和某人幽会！！！\n";
        message("channel:chat", RED+"【江湖通告】"+mesg+NOR, users() );
        message("channel:chat", GRN+"【江湖通告】"+mesg+NOR, users() );
        message("channel:chat", CYN+"【江湖通告】"+mesg+NOR, users() );
        return 1;}
}

int do_study(string arg)
{
    object me;

    me = this_player();

    if (! arg || (arg != "stone"))
        return notify_fail("你要研究什么？\n");

    if ((int)me->query_skill("literate", 1) < 1)
        return notify_fail("你是个文盲，先学点文化(literate)吧。\n");

    me->receive_damage("jing", 30);

    message_vision("$N正专心研读石坪上的「金刚经」。\n", me);

    if ((int)me->query_skill("buddhism", 1) < 100)
    {
        me->improve_skill("buddhism", 1 + random(me->query("int")));
        write("你对着石坪上的「金刚经」琢磨了一回"
                      "儿，似乎对禅宗心法略有心得。\n");
        return 1;
    }

    write("你对着石坪瞧了一回儿，发现上面所说的佛理太过"
              "浅显，对你来说已毫无意义了。\n");

    return 1;
}

int do_bed()
{       object me;
        me=this_player();
        message_vision(HIY "$N掀开纱帐，准备上床了。\n\n" NOR, me);
        me->move(__DIR__"bed");
        message_vision(HIY "\n沙帐轻轻一动，$N钻了进来。\n" NOR, me);
        return 1;
}

int do_lclose(string arg)
{
        object me;

        me = this_player();
        if (wiz_level(me) < 3)
                return notify_fail("你没有资格关闭擂台。\n");

        if (arg != "here")
                return notify_fail("如果你要关闭擂台，请输入(lclose here)。\n");

        if (objectp(query("close_by")))
                return notify_fail("这个擂台已经被" +
                                   query("close_by")->name(1) +
                                   "关闭用于比武了。\n");

        set("close_by", me);
        message("vision", HIW "【武林盛会】" + me->name(1) +
                "关闭了擂台，开始举行比武盛会。\n" NOR,
                all_interactive());
        return 1;
}

int do_pan()
{
        object me = this_player();
        me->move(__DIR__"shiya");
        return 1;
}

int do_mianbi()
{
    object me = this_player();

    message_vision("$N面对着达摩洞後半边的石壁跌坐静思，良久，似有所悟。\n", me);

    me->set_busy(10);
    me->set("shen", 0);

    return 1;
}

int do_move(string arg)
{
        object me;

        me = this_player();
        if (arg != "bed") return 0;
        message_vision("$N用力把小床移开，发现里面竟然有一条秘密通道！\n", me);
        me->move(__DIR__"midao1");
        tell_object(me, "接着是一阵轰隆隆的响声，你定神一看，自己已经处身在秘密通道中了。\n");
        return 1;
}

int do_climb(string arg)
{
        object me = this_player();

          if (! arg || arg != "stone")
                return notify_fail("你想爬什么？\n");

        write(HIG "\n你踩着洞中突出的石头上，很快爬出了洞口。\n\n" NOR);

        me->move(__DIR__"furongfeng");

        return 1;
}

int do_jump()
{
        object me = this_player();

        if (me->is_busy() || me->is_fighting())
              return notify_fail("你忙完了再说吧！\n");

        message_vision(HIG "$N" HIG "纵身跳上瀑布 ……\n", me);

        me->move(__DIR__"shanhongpb");

        return 1;
}

int do_caiqi(string arg)
{
//      mapping fam;
        object me;
        me = this_player();

        if ( ! living(me)) return 0;
        if ( ! living(this_player()) || arg != "song" )
        {
                message_vision("你想干什么？\n",me);
                return 1;
        }

        if( me->is_busy() )
                return notify_fail("你现在正忙着呢。\n");

        if ((int)me->query_skill("force",1) > 100)
                return notify_fail("依照你的内功修为已经再无法从树中吸取任何东西了！\n");

        if ((int)me->query_skill("force", 1) < 30 )
                return notify_fail("你的内功修为太低了，没办法从树中采气！\n");

        if (! me->can_improve_skill("force"))
                return notify_fail("你的实战经验不够，无法再加深你的内功！\n");

        if((int)me->query("jing") < 40)
        {
                write("你忽然觉得精神不济，无法控制体内的真气！\n");
                return 1;
        }

        me->receive_damage("jing", 30);
        message_vision(HIW "$N" HIW "闭上双眼，双手紧紧地贴住树干，开始缓缓吐呐练功。\n" NOR, me);
        me->improve_skill("force", me->query("con") * 2 / 3);
        me->start_busy(random(2));
        return 1;
}

int do_leave()
{
        object me = this_player();
        if (me->query_temp("want_leave")) 
        {
                tell_object(me, HIR "你决定离开万安寺。\n" NOR);
                me->move("/d/heimuya/road3");
        }
        return 1;
}

int do_leave(string  arg)
{
    string s;
    object me = this_player();
    if(!me->query_temp("weiqi_seat"))
        return notify_fail("你没有在下棋。\n");
    s = (string)me->query_temp("weiqi_seat");
    message_vision("$N不想再下了，站了起来。\n",me);
    map_delete(pl,s);
    me->delete_temp("weiqi_seat");
    status = WQ_NOT_PLAYING;
    delete_temp("action");
    return  1;
}

