int do_enter(string arg)
{
        object me = this_player();

        if (! arg || arg != "dong")
        {
                write("你想干什么呀?\n");
                return 1;
        }
        message_vision(HIY "$N" HIY "深吸了一口气，慢慢沿着"
                       "洞壁往外爬。\n" NOR, me);
        me->move(__DIR__"gudi2");
        return 1;
}

int do_cha(string arg)
{       
//      mapping fam;
        object me;
        me = this_player();

        if ( ! living(me)) return 0;
        if ( ! living(this_player()) || arg != "huo" )
        {
                write("你想往哪儿插呀！\n");
                return 1;
        }

        if( me->is_busy() )
                return notify_fail("你现在正忙着呢。\n");

        if ( (int)me->query_skill("strike", 1) < 30 )
                return notify_fail("你将双手插入镬中，灼热的铁沙登时烫得你怪叫不止，看来还是吧掌法练高点再来吧。\n");

        if ( (int)me->query_skill("strike", 1) > 100)
                return notify_fail("你将双手插入镬中，发现用铁沙练习已丝毫提高不了你的掌法了。\n");

        if (! me->can_improve_skill("strike"))
                return notify_fail("你的实战经验不够，无法再加深你的掌法！\n");

        if((int)me->query("qi") < 40)
        {
                write("你觉得一股热气直逼上来，焦燥难当。还是休息一下再接着练吧！\n");
                return 1;
        }

        me->receive_damage("qi", 30);
        me->improve_skill("strike", me->query("con") * 2);
        me->start_busy(random(2));
        message_vision(HIR "\n$N" HIR "将双手插进镬中的铁沙里。\n" NOR, me);
        write(RED "灼热的铁沙将你的双手烫得通红，你觉得双手登时变得更加强壮有力了。\n" NOR);
        return 1;
}

int do_jump(string arg)
{
    object me = this_player();

    if( !arg || arg != "chi")
    {
        write("你往哪里跳呀? \n");
        return 1;
    }

    message_vision(HIC "\n$N "HIC "往太乙池中跳去。\n", me);
    me->move("/d/gumu/taiyi2");
    message_vision(HIW "\n$N" HIC "跳进了太乙池中来。\n", me);
    return 1;
}

int do_climb(string arg)
{
        object me = this_player();

        if( !arg || arg != "up")
        {
                write("那个方向没法爬。\n");
                return 1;
        }

        message_vision("$N在太乙池中往岸上爬了上去。\n", me);
        me->move("/d/gumu/taiyi1");
        message_vision("$N从太乙池中爬了上去。\n", me);
        return 1;
}

int do_climb(string arg)
{
        object me = this_player();

        if (me->is_busy() || me->is_fighting())
