        message_vision(HIG "$N" HIG "拉着青藤爬上悬崖……\n", me);

        me->move("/d/huashan/chaoyang");

        me->start_busy(2);

        return 1;
}

int do_zou(string arg)
{       
        object me = this_player();

        if (me->is_busy() || me->is_fighting())
             return notify_fail("你还是忙完了再说吧！\n");

        message_vision(HIY "$N" HIY "快步向前走去 ……\n" NOR, me);

        me->move("/d/lanzhou/guangchang");

        me->start_busy(2);

        return 1;
}

int do_jump(string arg)
{
        object me;

        me = this_player();
        if (! arg)
        {
        message_vision("$N一闭眼，向潭中跳了下去，只觉冰冷刺"
                   "骨，赶紧运气相抗。\n",me);
                me->move("/d/mingjiao/hsqtan1");
                return 1;
        }

    return notify_fail("你要跳到哪儿？\n");
}

int do_hit(string arg)
{
    object me;

    me = this_player();
    if (! arg || ( arg != "drum" ))
                return notify_fail("你要敲什麽？\n");

    me->receive_damage("qi", 30);

    if (random(me->query("dex")) < 5)
    {
        message_vision("$N一不小心敲到自己头上了。\n", me);
        me->unconcious();
    } else
    {
        mapping mine;

        mine = me->query_entire_dbase();
        message_vision("$N敲了一下大鼓，『咚……』声音传遍整个寺庙。\n", me);
        write("鼓声如迅雷般在你耳边炸响，你头脑中一片糊涂，\n"
            "全身摇摇欲坠，勉力支撑着不倒在地上。心中一个\n"
            "声音告诉你，得赶快离开这里，不然就没命了。\n");
                if (random(2) == 0)
                {
                        if (mine["potential"] - mine["learned_points"] < 100)
                        mine["potential"] += 1;
                } else
                {
                        if (mine["potential"] - mine["learned_points"] > 0)
                        mine["potential"] -= 1;
                }
    }
    return 1;
}

int do_tiao(string arg)
{
        object me;
        //object weapon;
        me = this_player();

        if (! living(me) || arg != "shakeng")
                return notify_fail("你要击打什么？\n");

        if (me->is_busy())
                return notify_fail("你现在正忙着呢。\n");

        if ((int)me->query_skill("dodge", 1) < 30
           || (int)me->query_skill("bagua-bu", 1) < 30)
                return notify_fail("你憋足气朝着沙坑跳去，结果一跤重重地摔在了坑中。\n");

        if ((int)me->query_skill("dodge", 1) >= 120
           && (int)me->query_skill("bagua-bu", 1) >= 120)
                return notify_fail("你在沙坑周围跳了一会儿，发现在这里练习已经没什么用了。\n");

        if ((int)me->query("qi") < 40)
                return notify_fail("你现在累得脚都抬不起来了，还是先休息一会儿吧！\n");

        me->receive_damage("qi", 30);

        if (me->can_improve_skill("dodge")
           && (int)me->query_skill("dodge", 1) < 120)
                me->improve_skill("dodge", me->query("con") * 2);

        if (me->can_improve_skill("bagua-bu")
           && (int)me->query_skill("bagua-bu", 1) < 120)
                me->improve_skill("bagua-bu", me->query("con") * 2);

        me->start_busy(random(2));
        message_vision(WHT "\n$N" WHT "深吸一口气，“飕”的一声跳过了沙坑，接着翻身一纵"
                       "又跳了回来。\n" NOR, me);
        write(HIC "你对「八卦步法」及「基本轻功」有了新的理解。\n" NOR);
        return 1;
}

