int do_mianbi(string arg)
{
    object ob = this_player();

    if (!arg)
    {
        message_vision("$N面对着石柱趺坐静思良久，白"
                       "忙一场，一无所获。\n", ob);
        return 1;
    }

    if ((int)ob->query_skill("literate", 1) < 100)
    {
        message_vision("$N面对着石柱上满面蝌蚪文，没"
                       "一个字认识。\n", ob);
        return 1;
    }

    if ((int)ob->query_skill("taoism", 1) < 100)
    {
        message_vision("$N对石柱上每一个字都认识，就"
                       "是不知道说的是什么。\n", ob);
        return 1;
    }

    if (arg == "taiji-jian" ||
        arg == "taiji-quan" ||
        arg == "tiyunzong")
    {
        if ((int)ob->query_skill(arg, 1) < 100)
        {
            message_vision("$N的" + to_chinese(arg) + "显然太低，无法领悟石柱内容。\n", ob);
            return 1;
        }

        if ((int)ob->query_skill(arg, 1) > 180)
        {
            message_vision("$N的" + to_chinese(arg) + "已经没必要读石柱内容了。\n", ob);
            return 1;
        }

        if (!ob->can_improve_skill(arg))
        {
            message_vision("$N的实战经验不足，无法领悟石柱内容。\n", ob);
            return 1;
        }

        if (ob->query("jing") < 150)
        {
            message_vision("$N太累了，现在无法领悟石柱内容。\n", ob);
            return 1;
        }
        ob->improve_skill(arg, 1 + random(ob->query("int")));
        ob->add("jing", -100 - random(50));
        message_vision(HIY "$N" HIY "面对着石柱趺坐静思，过得良"
                           "久，似有所悟。\n" NOR, ob);
        write(HIC "你对「" + to_chinese(arg) + HIC "」有了新的理解。\n" NOR);
        return 1;
    }
    else
        message_vision(HIY "$N" HIY "面对着石柱趺坐静思良久，但似乎没什么启发。\n" NOR, ob);
    return 1;
}

int do_amble()
{
        object me;
        int lvl;

        me = this_player();

        if (me->is_busy())
                return notify_fail("你现在忙着呢。\n");

        if (me->is_fighting())
                return notify_fail("你正忙着打架呢。\n");

        me->start_busy(2 + random(3));
        if (! is_valid())
        {
                write("你在院子里面慢慢的溜达了一圈，满惬意，就是太无聊了。\n");
                return 1;
        }

        if (me->query("neili") < 100)
        {
                write("你看了看满院的积雪，提了一口真气，忽然觉得内力有些不济。\n");
                return 1;
        }

        me->add("neili", -50 - random(50));
        write("你深吸一口气，脚点积雪，轻飘飘的迈开步去。\n");
        lvl = me->query_skill("sixiang-bufa", 1);
        if (lvl < 50)
        {
                message_vision("$N晃晃悠悠的走了两步，“噗”的一下脚深深的"
                               "陷入了雪中，一脸懊丧之色。\n", me);
                return 1;
        } else
        if (lvl < 100)
        {
                message_vision("$N勉勉强强的绕着院子走了一圈，留了一地深浅"
                               "不一的脚印，惹得众人大笑。\n", me);
                return 1;
        }

        switch (random(3))
        {
        case 0:
                message_vision("$N哈哈一笑，双足连环踏雪而走，身"
                               "形飘洒之极！\n", me);
                break;

        case 1:
                message_vision("$N脸色木然，只是不住的凝神前行，"
                               "背后几乎没有留下半点脚印。\n", me);
                break;

        default:
                message_vision("$N迈开大步，一步步的走了出去，不"
                               "一会儿便走了一圈，自顾坐下冥神思索。\n", me);
                break;
        }

        if (me->can_improve_skill("dodge"))
                me->improve_skill("dodge", lvl / 2 + random(lvl / 2));

        if (me->can_improve_skill("sixiang-bufa"))
                me->improve_skill("sixiang-bufa", lvl / 2 + random(lvl / 2));
        return 1;
}

