        {
            write(HIC "\n你试着扭动门环，发现门环似乎可以左右滑动。\n" NOR);
            delete("left_trigger");
            delete("right_trigger");
            return 1;
        }
    }

    if (sscanf(arg, "huan %s", dir) == 1)
    {
        if (me->query("max_neili") < 300)
        {
            write(HIC "\n你使足劲扭动门环，可是门环还是纹丝不动。\n" NOR);
            return 1;
