int do_wash(string arg)
{
    int tmpstr, tmpint, tmpcon, tmpdex;
    object me;
    mapping my;

    if (!objectp(me = this_player()) ||
        !userp(me))
        return 1;

    if (!arg || sscanf(arg, "%d %d %d %d", tmpstr, tmpint, tmpcon, tmpdex) != 4)
        return notify_fail("指令格式：washto <膂力> <悟性> <根骨> <身法>\n      如：washto 20 20 20 20\n属性帮助：help attribute\n");
    if (tmpstr > 30)
        return notify_fail("你所选择的膂力参数不能大于30。\n");
    if (tmpstr < 10)
        return notify_fail("你所选择的膂力参数不能小于10。\n");
    if (tmpint > 30)
        return notify_fail("你所选择的悟性参数不能大于30。\n");
    if (tmpint < 10)
        return notify_fail("你所选择的悟性参数不能小于10。\n");
    if (tmpcon > 30)
        return notify_fail("你所选择的根骨参数不能大于30。\n");
    if (tmpcon < 10)
        return notify_fail("你所选择的根骨参数不能小于10。\n");
    if (tmpdex > 30)
        return notify_fail("你所选择的身法参数不能大于30。\n");
    if (tmpdex < 10)
        return notify_fail("你所选择的身法参数不能小于10。\n");
    if ((tmpstr + tmpint + tmpcon + tmpdex) != 80)
        return notify_fail("你所选择的属性总和必须为80。\n");

    write(HIC "你跳入忘忧池，顿时被一股激流卷了进去。\n" NOR, me);

    my = me->query_entire_dbase();

    my["str"] = tmpstr;
    my["int"] = tmpint;
    my["con"] = tmpcon;
    my["dex"] = tmpdex;
    my["kar"] = 5 + random(26);
    my["per"] = 5 + random(26);

    write(HIC "只听“啪”的一声，你被湿漉漉的抛了出来。\n" NOR, me);
    write(sprintf(HIY "\n你这次获得的四项先天天赋分别是：\n"
                      "膂力：【 " HIG "%d" HIY " 】 "
                      "悟性：【 " HIG "%d" HIY " 】 "
                      "根骨：【 " HIG "%d" HIY " 】 "
                      "身法：【 " HIG "%d" HIY " 】\n"
                      "如果你满意，就去投胎(born)吧！方法如" HIR "<born 扬州人氏>\n\n" NOR,
                  tmpstr, tmpint, tmpcon, tmpdex));
    me->set_temp("washed", 1);

    return 1;
}

