        if (arg != "cao")
        {
                write("你要拿什么呀！\n");
                return 1;
        }

        message_vision("$N在悬崖前站定，深呼一口气，突然跃起。\n", me);

        if (n >= 150)
        {
                if (query("caocount") > 0)
                {
                        message_vision("只见$N的身子在空中打了几个盘旋，身子轻飘"
                                       "飘落回，手中多了一物。\n", me);
                        obn = new(__DIR__"obj/cao");
                        obn->move(me, 1);
                        add("caocount", -1);
                } else
                        message_vision("$N定睛一看，发现草早被人拿走了，只剩一点草根了。\n",
                                       me);
        } else
        {
                me->receive_damage("qi", 50);
                me->receive_wound("qi", 50);
                message_vision(HIR "只见$N" HIR "的身子在空中打了几个盘旋，呀！不好！！！\n" NOR,
                               me);
                me->move(__DIR__"gudi");
                tell_object(me,HIR "你从悬崖上摔了下来，浑身疼痛，受了好几处伤。\n" NOR);
                message("vision", HIR "只见" + me->name() + HIR "你从悬崖上摔了下来，"
                                  "躺在地上，半天不动。\n" NOR, environment(me), me);
        }
        return 1;
}

int do_pick(string arg)
{
        object me = this_player();
        object ob, noname, xuantie;

        if (me->is_busy() || me->is_fighting())
              return notify_fail("你忙完了再说吧！\n");

        if (! arg || 
            arg != "fir sword" &&
            arg != "sec sword" &&
            arg != "thi sword")
              return notify_fail("你要取什么？\n");

        if (! ob = find_object(__FILE__));
                 ob = load_object(__FILE__);

        if (! noname = find_object(NONAME));
                 noname = load_object(NONAME);

        if (! xuantie = find_object(XUANTIE));
                 xuantie = load_object(XUANTIE);

        if (! ob->query_temp("moved"))
                 return notify_fail("你要干什么？\n");

        switch(arg)
        {
              case "fir sword" : 
                     return notify_fail(HIC "你将竹剑拿起来看了看，觉得普通之极，便又放了回去。\n" NOR);

              case "sec sword":
                     if (environment(xuantie))
                           return notify_fail("上面的东西已被人拿走了！\n");

                     if (me->query("str") < 34)
                           return notify_fail("你将铁剑只提起数尺，呛的一声，竟然脱手掉下"
                                              "，在石上一碰，火花四溅，不禁吓了一跳。\n");

                     message_vision(HIM "$N" HIM "将玄铁重剑提了起来。\n" NOR, me);

                     xuantie->move(me);

                     return 1;

              case "thi sword":
                     if (environment(noname))
                           return notify_fail("上面的东西已被人拿走了！\n");

                     message_vision(HIM "$N" HIM "将无名剑提了起来。\n" NOR, me);

                     noname->move(me);

                     return 1;
        }

        me->start_busy(1);

        return 1;
}

int do_enter(string arg)
{
        object ob, lingpai;
