        if (! me->query_temp("working_in_huozhan"))
        {
                if (me->query("qi") < 25 ||
                    me->query("jing") < 25)
                        return notify_fail("你可是累坏了，干不动了。\n");

                message_vision("$N从车上卸下一袋袋的大米，又"
