int do_jiaoshui()
{
    object me, ob;
    int exp, pot;

    me = this_player();

    if (me->query("jing") < 50)
    {
        tell_object(me, "你已经很疲惫了，休息一下再接着种吧。\n");
        return 1;
    }
    if (me->is_busy())
    {
        tell_object(me, "你正忙着呢，别着急。\n");
        return 1;
    }
    if (!me->query_temp("peiyu") == 1)
    {
        tell_object(me, "你没事干浇什么水啊！\n");
        return 1;
    }
    if (me->query_temp("peiyu") == 2)
    {
        // 成功率
        if (random(10) < highest(random(me->query("mark/job_zhonghua")), 5))
        {
            // 记录种花成功次数
            me->add("mark/job_zhonghua", 1);
            switch (random(5))
            {
            case 1:
                ob = new ("/d/changan/npc/obj/hmeigui");
                break;
            case 2:
                ob = new ("/d/changan/npc/obj/zi-luolan");
                break;
            case 3:
                ob = new ("/d/changan/npc/obj/bai-chahua");
                break;
            case 4:
                ob = new ("/d/changan/npc/obj/huang-meigui");
                break;
            case 0:
                ob = new ("/d/changan/npc/obj/lan-tiane");
                break;
            }

            if (random(15) == 1)
            {
                if (random(100) < 5) //增加奖励机率（2015-04-01）
                {
                    ob = new ("/d/shenlong/obj/hua4");
                    message_vision(HIY "$N" HIY "种出了一朵翡翠兰。\n" NOR, me);
                    ob->move(me, 1);
                    me->delete_temp("jiaoshui");
                    me->delete_temp("zhonghua");
                    me->delete_temp("peiyu");
                    me->add("combat_exp", 500);
                    me->improve_potential(100 + random(100));
                    return 1;
                }
                ob = new ("/d/shenlong/obj/hua2");
                me->add("combat_exp", 90 + random(10));
                me->improve_potential(90 + random(10));
                message_vision(HIY "$N" HIY "种出了一朵无名花。\n" NOR, me);
                return 1;
            }
            message_vision(HIC "$N" HIC "十分小心的给小坑里浇了一些"
                               "水，突然一朵" +
                               ob->query("name") + HIC "从坑里冒了出来。\n" NOR,
                           me);
            message_vision(HIY "$N" HIY "把它摘了下来，拿在手里。\n" NOR, me);
            ob->move(me, 1);
            me->delete_temp("jiaoshui");
            me->delete_temp("peiyu");
            me->delete_temp("zhonghua");
            //增加奖励5倍
            exp = 50 + random(10);
            pot = 20 + random(10);

            if (me->query("potential") > me->query_potential_limit())
                pot = 1;

            me->add("combat_exp", exp);
            me->improve_potential(pot);

            tell_object(me, HIC "通过这次训练，你获得了" + chinese_number(exp) + "点经验和" + chinese_number(pot) + "点潜能。\n" NOR);
            return 1;
        }
        message_vision(HIR "$N" HIR "笨手笨脚的拿起水壶给小坑里浇水，结"
                           "果水洒的太多把花给毁了。\n",
                       me);
        me->delete_temp("jiaoshui");
        me->delete_temp("zhonghua");
        me->delete_temp("peiyu");
        me->add("jing", -20);
        me->add("combat_exp", 7);
        me->improve_potential(3);
        return 1;
    }
    if (me->query_temp("jiaoshui") == 1)
    {
        message_vision(HIC "$N" HIC "拿起水壶给小坑浇了一些水。\n" NOR, me);
        me->add("jing", -30);
        me->set_temp("peiyu", 2);
        me->start_busy(1 + random(2));
        return 1;
    }
}

int do_bet(string arg)
{
    object me = this_player();
    string what;
    int amount;
    string money;
    object ob;
    object zj;

    if (! objectp(zj = present("zhuang jia", this_object())))
            return notify_fail("庄家都没有，你要和谁赌？\n");

    if (! living(zj))
            return notify_fail("你还是等庄家醒了再说吧！\n");

    if (! arg || sscanf (arg,"%s %d %s", what, amount, money) != 3)
            return notify_fail(CYN "赌客讥笑道：哪里有你那样赌钱的？\n" NOR);

    if (what != "tc" &&
        what != "sd" &&
        what != "qx" &&
        what != "sx")
            return notify_fail(CYN "庄家皱眉道：你要押哪一种骰？\n" NOR);

    ob = present(money + "_money", me);
    if (! ob)
            return notify_fail(CYN "庄家皱眉道：你身上没有这种钱吧？\n" NOR);

    if (amount < 1)
            return notify_fail(CYN "庄家皱眉道：那么少？不够，不够，再多押点。\n" NOR);

    if (amount > ob->query_amount())
            return notify_fail(CYN "庄家皱眉道：你有那么多钱吗？\n" NOR);

if (amount > 10)
    return notify_fail(CYN "庄家喊道：怎么零零碎碎的那么多？换成整票再来下注！\n" NOR);

if (ob->query("base_value") * amount > 100000)
    return notify_fail(CYN "庄家大声道：赌注最大十两黄金。\n" NOR);

    if (me->query_temp("gamble_bet/amount") > 0)
            return notify_fail(CYN "庄家道：你已经押过了，就等着开盅吧。\n" NOR);

    if (room_status > 1)
            return notify_fail(CYN "庄家赔笑道：现在正在赌呢，请你稍等片刻。\n" NOR);

    me->set_temp("gamble_bet/kind", what);
    me->set_temp("gamble_bet/amount", amount);
    me->set_temp("gamble_bet/money", money);
    message_vision(sprintf("$N拿出%s%s%s，押在%s上。\n",
                            chinese_number(amount),
                            ob->query("base_unit"),
                            ob->query("name"),
                            gutous[what]),
                            me);
    if (amount == ob->query_amount())
            destruct (ob);
    else
            ob->add_amount(-amount);

    if (! arrayp(query_temp("better")))
            set_temp("better", ({ me }));
    else
            add_temp("better", ({ me }));

    return 1;
}

