            return 1;
        }
       write(HIC "你对「乘风破浪」这招有了新的认识，但是仍有许多不解之处。\n" NOR);
       me->start_busy(2 + random(4));
       return 1;
    }

    else
    if (random(20) == 1 && witch == "白首太玄经")
    {
        me->add("taixuan_perform/bai/count", 1);

        if (me->query("taixuan_perform/bai/count") >= 100)
