int do_push()
{
        object ob;
        object me;
        object room;

        if (query("gate") == "open")
                return notify_fail("大门开着呢，你还推什么？\n");

        me = this_player();
        ob = present("saodi laopu", this_object());
        if (me && (! ob || ! living(ob) || ob->is_owner_permit(me)))
        {
                message_vision("$N用力一推大门，就听见大门“吱呀呀”的开了。\n",
                               me);
        } else
        if (me && ! ob->is_owner(me))
        {
                message_vision("$N伸手拦住$n，客客气气道：“对不起，这位" +
                               RANK_D->query_respect(me) + "还是请回"
                               "吧！”\n", ob, me);
                return 1;
        } else
        if (ob && living(ob))
        {
                message_vision("$n连忙跑上前来，对$N道：“主人何必亲"
                        "劳，我来吧！”\n$n走上前去，用力将大门“吱呀"
                        "呀”的推开了。\n", me, ob);
        } else
        {
                message("vision",  "大门“吱呀呀”的被人打开了。\n",
                        this_object());
        }

        room = get_object(__DIR__"zoudao");
        message("vision", "大门“吱呀呀”的被人推开了。\n", room);
        set("gate", "open");
        set("exits/north", __DIR__"zoudao");
        room->set("exits/south", __FILE__);
        room->set("gate", "open");
        remove_call_out("do_close");
        call_out("do_close", 10, 0, 1);
        return 1;
}

int do_lianzhi (string arg)
{
        object /*ob,*/ me = this_player();
        int time = 15 + random(15);

        if (me->query("family/family_name") != "五毒教")
                return notify_fail("你不知道该如何下手。\n");

        if (me->query_temp("liandu/wudu"))
                return notify_fail("你现在正炼着呢，切勿分心。\n");

        if (me->is_busy())
                return notify_fail("你现在正忙着呢。\n");

        if (me->query_skill("wudu-qishu", 1) < 60 )
                return notify_fail("你的五毒奇术不够娴熟，无法炼毒。\n");

        if (me->query("jing") < 80 || me->query("qi") < 80)
                return notify_fail("你现在的精神状况不佳，无法炼毒。\n");

        if (arg != "heding hong" && arg != "furou gao" &&
            arg != "kongque dan" && arg != "chixie fen" &&
            arg != "wusheng san" && arg != "duanchang san")
            return notify_fail("你要炼制什么毒药？\n");

        if (arg == "heding hong")
        {
                if (! present("du nang", me)
                   || ! present("shexin zi", me)
                   || ! present("qianri zui", me))
                        return notify_fail("你身上的原料不齐，无法炼毒。\n");

                destruct(present("du nang", me));
                destruct(present("shexin zi", me));
                destruct(present("qianri zui", me));
                me->set_temp("liandu/wudu", "hedinghong");
        } else

        if (arg == "furou gao")
        {
                if (! present("du nang", me)
                   || ! present("fugu cao", me)
                   || ! present("chuanxin lian", me))
                        return notify_fail("你身上的原料不齐，无法炼毒。\n");

                destruct(present("du nang", me));
                destruct(present("fugu cao", me));
                destruct(present("chuanxin lian", me));
                me->set_temp("liandu/wudu", "furougao");
        } else

        if (arg == "kongque dan")
        {
                if (! present("du nang", me)
                   || ! present("fugu cao", me)
                   || ! present("qianri zui", me))
                        return notify_fail("你身上的原料不齐，无法炼毒。\n");

                destruct(present("du nang", me));
                destruct(present("fugu cao", me));
                destruct(present("qianri zui", me));
                me->set_temp("liandu/wudu", "kongquedan");
        } else

        if (arg == "chixie fen")
        {
                if (! present("du nang", me)
                   || ! present("shexin zi", me)
                   || ! present("duanchang cao", me))
                        return notify_fail("你身上的原料不齐，无法炼毒。\n");

                destruct(present("du nang", me));
                destruct(present("shexin zi", me));
                destruct(present("duanchang cao", me));
                me->set_temp("liandu/wudu", "chixiefen");
        } else

        if (arg == "duanchang san")
        {
                if (! present("du nang", me)
                   || ! present("duanchang cao", me)
                   || ! present("chuanxin lian", me))
                        return notify_fail("你身上的原料不齐，无法炼毒。\n");

                destruct(present("du nang", me));
                destruct(present("duanchang cao", me));
                destruct(present("chuanxin lian", me));
                me->set_temp("liandu/wudu", "duanchangsan");
        } else

        if (arg == "wusheng san")
        {
                if (! present("du nang", me)
                   || ! present("heding hong", me)
                   || ! present("duanchang san", me)
                   || ! present("furou gao", me)
                   || ! present("chixie fen", me)
                   || ! present("kongque dan", me)
                   || ! present("jinshe duye", me))
                        return notify_fail("你身上的原料不齐，无法炼毒。\n");

                destruct(present("du nang", me));
                destruct(present("heding hong", me));
                destruct(present("duanchang san", me));
                destruct(present("furou gao", me));
                destruct(present("chixie fen", me));
                destruct(present("kongque dan", me));
                destruct(present("jinshe duye", me));
                me->set_temp("liandu/wudu", "wushengsan");
        }

        message_vision (HIR "\n$N" HIR "将身上的药品投入丹炉，按照秘法小心"
                        "炼制起来。\n\n" NOR, me);
        me->start_call_out((: call_other, __FILE__, "liandu", me :), time);
        me->start_busy(time / 2 + 1);
        return 1;
}

int do_knock(string arg)
{
        object room, me = this_player();

        if (query("exits/north"))
                return notify_fail("门已经是开着的，不用再费力去敲了！\n");

        if (arg == "4")
        {
                message_vision(HIC "$N" HIC "走上前去将门上铜环敲了四下。\n" NOR, me);
                me->set_temp("step", 1);
                return 1;
        }

        if (arg == "2")
        {
                message_vision(HIC "$N" HIC "走上前去将门上铜环敲了两下。\n" NOR, me);
                if (me->query_temp("step") == 1)
                        me->set_temp("step", 2);
                else
                        me->set_temp("step", 0);
                return 1;
        }

        if (arg == "5")
        {
                message_vision(HIC "$N" HIC "走上前去将门上铜环敲了五下。\n" NOR, me);
                if (me->query_temp("step") == 2)
                        me->set_temp("step", 3);
                else
                        me->set_temp("step", 0);
                return 1;
        }

        if (arg == "3")
        {
                message_vision(HIC "$N" HIC "走上前去将门上铜环敲了三下。\n" NOR, me);
                if (me->query_temp("step") == 3)
                {
                        me->set_temp("step", 0);
                        set("exits/north", __DIR__"tianjing");
                        message("vision", HIY "你静静的等候，过了半晌，大门终于缓缓"
                                          "的打开了。\n" NOR, this_object() );

                        if (! (room = find_object(__DIR__"tianjing")))
                                room = load_object(__DIR__"tianjing");

                        room->set("exits/south", __FILE__);
                        message("vision", HIY "梅庄大门上的铜环有节奏地响了"
                                "四声，大门给打开了。\n" NOR, room );
                        remove_call_out("close_passage");
                        call_out("close_passage", 10);
                } else
                {
                        me->set_temp("step", 0);
                }
                return 1;
        }
        message_vision(HIC "$N" HIC "走上前去将门上铜环敲了几下。\n" NOR, me);
        return 1;
}

int do_born(string arg)
{
    object me;
    object obj;
    object item;
    mixed dest;
    string new_name;
    string msg;

    if (!objectp(me = this_player()) ||
        !userp(me))
        return 1;

    if (!me->query_temp("washed") && !me->query("reborn"))
        return notify_fail("你先在忘忧池中洗一下(washto)，选择好天赋你再投胎也不迟啊！\n");

    if (arg && arg[0] < 160)
        return notify_fail("你必须输入中文地名，比如：" HIY "born 扬州人氏" NOR "，以避免投错胎。\n");

    new_name = 0;
    if (arg)
        sscanf(arg, "%s %s", arg, new_name);

    if (!arg || (!stringp(dest = born[arg]) && !mapp(dest)))
    {
        message_vision(CYN "牛头恶狠狠的对$N" CYN "说：你要干什么！投胎去哪里？\n" NOR, me);
        return 1;
    }

    if (mapp(dest) && stringp(dest["notice"]))
        return notify_fail(dest["notice"]);

    if (stringp(dest))
    {
        if (!objectp(obj = find_object(dest)))
            obj = load_object(dest);
        me->set("startroom", dest);
        me->set("born", arg);
        me->set("born_family", "没有");
    }
    else
    {
        if (!objectp(obj = find_object(dest["startroom"])))
            obj = load_object(dest["startroom"]);
        me->set("startroom", dest["startroom"]);
        me->set("born", dest["born"]);
        me->set("born_family", arg);

        if (new_name)
        {
            if (!sscanf(new_name, dest["surname"] + "%*s"))
                new_name = dest["surname"] + new_name;

            if (strlen(new_name) > 4)
                return notify_fail("你的名字太长了。\n");

            if (strlen(new_name) < 2)
                return notify_fail("你的名字太短了。\n");

            if (!is_chinese(new_name))
                return notify_fail("请你用中文起名字。\n");
        }

        if (me->query("surname") != dest["surname"])
        {
            // 名字需要变化
            if (!new_name)
                new_name = dest["surname"] + me->query("purename");
            if (stringp(msg = NAME_D->invalid_new_name(new_name)))
            {
                write(msg);
                write("你可以考虑在投入世家的时候重新选择名字：born <世家> <名字>\n");
                return 1;
            }
            me->set("surname", dest["surname"]);
            me->set("purename", new_name[strlen(dest["surname"])..< 1]);
        }

        if (mapp(dest["family"]))
        {
            me->set("family", dest["family"]);
            me->assign_apprentice(dest["family"]["title"], 0);
        }
        me->set_name();
    }
    if (!objectp(obj))
    {
        message_vision(CYN "牛头一呆，搔搔头说道：怎么好像有问题……\n" NOR, me);
        return 1;
    }

    message_vision(HIC "牛头飞起一脚，将$N" HIC "踢了出去。\n" NOR, me);

    foreach (item in all_inventory(me))
        if (!item->query("armor_type") && !(item->query("id") == "heros book"))
        {
            if (item->is_character() || item->query("value"))
                item->move(environment(me));
            else
                destruct(item);
        }

    // 选择特殊技能
    if (!me->query("reborn"))
    {
        UPDATE_D->born_player(me);
    }
    me->move(obj);
    me->set("mud_age", 0);
    me->set("age", 14);
    me->set("registered", 1);
    me->save();
    // HELP_CMD->main(me, "rules");
    HELP_CMD->main(me, "topics");

    message_vision("$N揉揉眼睛，迷惘的望着这个陌生的世界。\n", me);

    return 1;
}
